function Eq([string]$id,[string]$sku,[string]$name='QA equipment',[string]$brand='QA'){@{id=$id;sku=$sku;name=$name;brand=$brand;category='QA category';direction='nku';unit='шт';purchase=123.45;ratedCurrent=16;attrs='qa'}}
function Request([string]$method,[string]$path,$body=$null,[string]$token='',[switch]$Raw){$headers=@{};if($token){$headers.Authorization="Bearer $token"};$args=@{Uri=$base+$path;Method=$method;Headers=$headers;TimeoutSec=20;SkipHttpErrorCheck=$true};if($null-ne$body){$args.ContentType='application/json';$args.Body=if($Raw){[string]$body}else{$body|ConvertTo-Json -Depth 20 -Compress}};$r=Invoke-WebRequest @args;$status=[int]$r.StatusCode;$text=if($r.Content-is[byte[]]){[Text.Encoding]::UTF8.GetString($r.Content)}else{[string]$r.Content};$json=if($text-and($text.TrimStart().StartsWith('{')-or$text.TrimStart().StartsWith('['))){$text|ConvertFrom-Json}else{$null};[pscustomobject]@{Status=$status;Json=$json;Text=$text}}
function ConcurrentPost($one,$two,[string]$token){$client=[Net.Http.HttpClient]::new();$client.Timeout=[TimeSpan]::FromSeconds(20);$client.DefaultRequestHeaders.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$token);$m1=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,"$base/api/catalog");$m2=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,"$base/api/catalog");$m1.Content=[Net.Http.StringContent]::new(($one|ConvertTo-Json -Depth 20 -Compress),[Text.Encoding]::UTF8,'application/json');$m2.Content=[Net.Http.StringContent]::new(($two|ConvertTo-Json -Depth 20 -Compress),[Text.Encoding]::UTF8,'application/json');try{$t1=$client.SendAsync($m1);$t2=$client.SendAsync($m2);[Threading.Tasks.Task]::WaitAll(@($t1,$t2));$r=@();foreach($t in @($t1,$t2)){$text=$t.Result.Content.ReadAsStringAsync().Result;$json=if($text-and$text.TrimStart().StartsWith('{')){$text|ConvertFrom-Json}else{$null};$r+=[pscustomobject]@{Status=[int]$t.Result.StatusCode;Json=$json;Text=$text}};$r}finally{$m1.Dispose();$m2.Dispose();$client.Dispose()}}
function ConcurrentCrossPost($one,$two,[string]$token){$client=[Net.Http.HttpClient]::new();$client.Timeout=[TimeSpan]::FromSeconds(20);$client.DefaultRequestHeaders.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$token);$m1=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,"$base/api/catalog");$m2=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,"$base2/api/catalog");$m1.Content=[Net.Http.StringContent]::new(($one|ConvertTo-Json -Depth 20 -Compress),[Text.Encoding]::UTF8,'application/json');$m2.Content=[Net.Http.StringContent]::new(($two|ConvertTo-Json -Depth 20 -Compress),[Text.Encoding]::UTF8,'application/json');try{$t1=$client.SendAsync($m1);$t2=$client.SendAsync($m2);[Threading.Tasks.Task]::WaitAll(@($t1,$t2));$r=@();foreach($t in @($t1,$t2)){$text=$t.Result.Content.ReadAsStringAsync().Result;$json=if($text-and$text.TrimStart().StartsWith('{')){$text|ConvertFrom-Json}else{$null};$r+=[pscustomobject]@{Status=[int]$t.Result.StatusCode;Json=$json;Text=$text}};$r}finally{$m1.Dispose();$m2.Dispose();$client.Dispose()}}function ConcurrentCross($method1,$path1,$body1,$method2,$path2,$body2,[string]$token){$client=[Net.Http.HttpClient]::new();$client.Timeout=[TimeSpan]::FromSeconds(20);$client.DefaultRequestHeaders.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$token);$m1=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::$method1,"$base$path1");$m2=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::$method2,"$base2$path2");$m1.Content=[Net.Http.StringContent]::new(($body1|ConvertTo-Json -Depth 20 -Compress),[Text.Encoding]::UTF8,'application/json');$m2.Content=[Net.Http.StringContent]::new(($body2|ConvertTo-Json -Depth 20 -Compress),[Text.Encoding]::UTF8,'application/json');try{$t1=$client.SendAsync($m1);$t2=$client.SendAsync($m2);[Threading.Tasks.Task]::WaitAll(@($t1,$t2));$r=@();foreach($t in @($t1,$t2)){$text=$t.Result.Content.ReadAsStringAsync().Result;$json=if($text-and$text.TrimStart().StartsWith('{')){$text|ConvertFrom-Json}else{$null};$r+=[pscustomobject]@{Status=[int]$t.Result.StatusCode;Json=$json;Text=$text}};$r}finally{$m1.Dispose();$m2.Dispose();$client.Dispose()}}function Sql([string]$query){(($query|& "$pgBin\psql.exe" -h 127.0.0.1 -p $pgPort -U postgres -d $db -tA).Trim())}
function ConcurrentCrossDelete([string]$id,[string]$token1,[string]$token2=$token1){$c1=[Net.Http.HttpClient]::new();$c2=[Net.Http.HttpClient]::new();$c1.Timeout=$c2.Timeout=[TimeSpan]::FromSeconds(20);$c1.DefaultRequestHeaders.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$token1);$c2.DefaultRequestHeaders.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$token2);try{$t1=$c1.DeleteAsync("$base/api/catalog/$id");$t2=$c2.DeleteAsync("$base2/api/catalog/$id");[Threading.Tasks.Task]::WaitAll(@($t1,$t2));@([int]$t1.Result.StatusCode,[int]$t2.Result.StatusCode)}finally{$c1.Dispose();$c2.Dispose()}}
